using System.Text.Json;
using System.Text.Json.Nodes;
using System.Security.Cryptography;
var opt=new JsonSerializerOptions(JsonSerializerDefaults.Web){WriteIndented=true};
var repo=Path.GetFullPath(args[0]); var root=Path.GetFullPath(args[1]);
if(Directory.Exists(root))throw new Exception("Use a fresh isolated fixture directory.");
Directory.CreateDirectory(Path.Combine(root,"data"));
var dataset=JsonNode.Parse(File.ReadAllText(Path.Combine(repo,".sim-state/data/rfq-intakes.json")))!;
var record=dataset["records"]!.AsArray().Single(r=>(string?)r!["intakeId"]=="RFQI-SIM-0045")!.DeepClone();
var id="RFQI-SIM-0045";var correlation=(string)record["requestCorrelationId"]!;
var unrelated=record.DeepClone();unrelated["intakeId"]="ISOLATED-UNRELATED";
var intakePath=Path.Combine(root,"data/rfq-intakes.json");var lanePath=Path.Combine(root,"data/rfq-lanes.json");
File.WriteAllText(intakePath,new JsonObject{["schema"]="DLE_RFQ_INTAKE_DATASET_V1",["records"]=new JsonArray(record,unrelated)}.ToJsonString());
var lane=JsonNode.Parse(File.ReadAllText(Path.Combine(repo,".sim-state/data/rfq-lanes.json")))![id]!.DeepClone();
File.WriteAllText(lanePath,new JsonObject{[id]=lane}.ToJsonString());
var sourceDir=Path.Combine(repo,".sim-state/intake-documents",correlation);var targetDir=Path.Combine(root,"intake-documents",correlation);Directory.CreateDirectory(targetDir);
foreach(var file in Directory.GetFiles(sourceDir))File.Copy(file,Path.Combine(targetDir,Path.GetFileName(file)));
var originalFiles=Directory.GetFiles(targetDir).ToDictionary(f=>f,f=>Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(f))));
var api=new SimRfqIntakeStore(root);var author=new SimPersona("test","test","Isolated Reviewer","ACTIVE",[],["technical_review.view","technical_review.disposition"],false,"SIM");
int checks=0;
void Check(bool ok,string why){if(!ok)throw new Exception(why);checks++;Console.WriteLine("PASS "+why);}
async Task Reject(Func<Task> f,string code){try{await f();throw new Exception("Expected "+code);}catch(SimRfqIntakeProblem e){Check(e.Code==code,code);}}
string J(object o)=>JsonSerializer.Serialize(o,opt);
var view=await api.ReadCustomerIdentity(id,author); var acceptedBefore=J(view.Accepted);
await Reject(()=>api.ReadCustomerIdentity(id,author with{Permissions=[]}),"CUSTOMER_IDENTITY_DENIED");
var mat=await api.ReadMaterials(id);
var rows=mat.Plan.Rows.Select(r=>r with{Vendor="Fixture vendor",VendorSource="MANUAL_QUOTE_ONLY",UnitPrice=2.25m,LeadTimeMode="STOCK",Uom="EA",MfgPartNumber=r.MfgPartNumber??"Fixture manufacturer number",MfgPartNumberSource=r.MfgPartNumberSource??"MANUAL_QUOTE_ONLY",Notes="Preserve sourcing notes",Charges=r.Index==0?[new SimMaterialCharge(Guid.NewGuid().ToString(),"Fixture fee","FREIGHT",5m,"BLEND","MATERIAL")]:null}).ToArray();
mat=await api.SaveMaterials(id,new(mat.Plan.Revision,rows,MarkupPercent:12,ChargeContractVersion:2,EvidenceContractVersion:1),author);
var att=await api.StageMaterialAttachment(id,new(mat.Plan.Revision,mat.Plan.CandidateId,mat.Plan.BomVersion,0,null,"FILE","VENDOR_QUOTE"),"quote.txt",new MemoryStream(System.Text.Encoding.UTF8.GetBytes("Fixture vendor quote")),author);
Console.WriteLine("Attachment fixture staged");
// Attach the verified upload and an authored note using its unchanged original owner.
var attachment=JsonSerializer.Deserialize<SimMaterialAttachment>(J(att),opt);
// Upload result may be an envelope; obtain the canonical attachment from it.
var attNode=JsonNode.Parse(J(att))!;
if(attNode["attachment"] is not null)attachment=attNode["attachment"]!.Deserialize<SimMaterialAttachment>(opt);
Check(attachment?.DocumentId is not null,"attachment metadata available");
rows=mat.Plan.Rows.Select(r=>r.Index==0?r with{Evidence=new([new(Guid.NewGuid().ToString(),SimRfqIntakeStore.MaterialOwner(mat.Plan,0),"SOURCING_PURCHASING","Keep this note")],[attachment!])}:r).ToArray();
mat=await api.SaveMaterials(id,new(mat.Plan.Revision,rows,Complete:true,MarkupPercent:12,ChargeContractVersion:2,EvidenceContractVersion:1),author);
var materialBefore=J(mat.Plan);var laborBefore=J((await api.ReadLabor(id)).Plan);
var process=await api.ReadBomProcess(id,author);
process=await api.SaveBomProcess(id,new(process.ContentToken,process.Revision,process.Rows.Select((r,i)=>i==0?r with{Notes="Preserve process note"}:r).ToArray()),author);
var processBefore=J(process.Rows);
view=await api.ReadCustomerIdentity(id,author);
var pdf=view.Sources.Single(s=>s.Name=="B11165-32 REV A.pdf");
string[] numbers=["C6X821","C6X570","C6X610","E9X004","E8X001"];
var changes=numbers.Select((n,i)=>{var r=view.Accepted.Candidate.Rows.Single(r=>r.Values["lineNumber"]==(i+2).ToString());return new SimCustomerIdentityChange(r.Index,r.RowId!,r.Values["partNumber"],n,[new(pdf.DocumentId,pdf.Sha256,"Page 2, P/N column, Find "+(i+2),n)]);}).ToArray();
var req=new SimCustomerIdentityRequest(view.Token,"Restore customer identifiers from original customer BOM",changes);
await Reject(()=>api.SaveCustomerIdentity(id,req with{Changes=[]},null,author),"CUSTOMER_IDENTITY_VALUES");
await Reject(()=>api.SaveCustomerIdentity(id,req with{Changes=[changes[0],changes[0]]},null,author),"CUSTOMER_IDENTITY_VALUES");
await Reject(()=>api.SaveCustomerIdentity(id,req with{Changes=[changes[0] with{Evidence=[changes[0].Evidence[0] with{QuotedNumber="conflict"}]}]},null,author),"CUSTOMER_IDENTITY_EVIDENCE");
await Reject(()=>api.SaveCustomerIdentity(id,req with{Changes=[changes[0] with{Evidence=[changes[0].Evidence[0] with{Sha256="bad"}]}]},null,author),"CUSTOMER_IDENTITY_EVIDENCE");
view=await api.SaveCustomerIdentity(id,req,null,author);
Check(J(view.Accepted)==acceptedBefore,"draft leaves accepted BOM unchanged");
File.WriteAllText(Path.Combine(root,"draft-view.json"),J(view));
await Reject(()=>api.SaveCustomerIdentity(id,req,null,author),"CUSTOMER_IDENTITY_STALE");
await Reject(()=>api.SaveCustomerIdentity(id,null,new(view.Token,view.History.Last().Id,true,false),author),"CUSTOMER_IDENTITY_REVIEW");
var staleToken=view.Token;
mat=await api.SaveMaterials(id,new(mat.Plan.Revision,mat.Plan.Rows,Complete:true,MarkupPercent:12,ChargeContractVersion:2,EvidenceContractVersion:1),author);
await Reject(()=>api.SaveCustomerIdentity(id,null,new(staleToken,view.History.Last().Id,true,true),author),"CUSTOMER_IDENTITY_STALE");
materialBefore=J(mat.Plan);var lanesBefore=File.ReadAllBytes(lanePath);
view=await api.ReadCustomerIdentity(id,author);view=await api.SaveCustomerIdentity(id,null,new(view.Token,view.History.Last().Id,true,true),author);
Check(view.Accepted.Version==2,"explicit acceptance creates version 2");
await Reject(()=>api.SaveCustomerIdentity(id,null,new(staleToken,view.History.Last().Id,true,true),author),"CUSTOMER_IDENTITY_STALE");
Check(File.ReadAllBytes(lanePath).SequenceEqual(lanesBefore),"acceptance leaves all lane bytes untouched");
Check(J((await api.ReadMaterials(id)).Plan)==materialBefore,"prices vendors evidence notes and completed material snapshots preserved");
Check(J((await api.ReadLabor(id)).Plan)==laborBefore,"completed labor preserved exactly");
Check(J((await api.ReadBomProcess(id,author)).Rows)==processBefore,"process notes retained through identity version");
Check((await api.ReadFinalReview(id)).Summary.MaterialsComplete,"completed materials remain usable for final review");
Check(view.Accepted.Candidate.Rows.Skip(1).Take(5).Select(r=>SimRfqIntakeStore.CustomerNumber(r)).SequenceEqual(numbers),"five customer identities projected");
var old=JsonNode.Parse(File.ReadAllText(intakePath))!["records"]![0]!["technicalReview"]!["bomAcceptances"]![0]!.Deserialize<SimBomAcceptance>(opt)!;
Check(J(old)==acceptedBefore,"accepted v1 immutable");
Check(view.Accepted.Candidate.Rows[5].Values["partNumber"]==old.Candidate.Rows[5].Values["partNumber"] && J(view.Accepted.Candidate.Rows[5].ManufacturerIdentity!)==J(old.Candidate.Rows[5].ManufacturerIdentity!),"FN6 manufacturer discrepancy untouched");
await Reject(()=>api.StageMaterialAttachment(id,new(mat.Plan.Revision,mat.Plan.CandidateId,mat.Plan.BomVersion,0,null,"FILE","VENDOR_QUOTE"),"stale.txt",new MemoryStream([65]),author),"MATERIALS_SOURCE_CHANGED");
await Reject(()=>api.SaveMaterials(id,new(mat.Plan.Revision,mat.Plan.Rows,ExpectedAcceptedBomVersion:1),author),"MATERIALS_SOURCE_CHANGED");
await Reject(()=>api.SaveMaterials(id,new(mat.Plan.Revision,mat.Plan.Rows),author),"MATERIALS_SOURCE_CHANGED");
mat=await api.SaveMaterials(id,new(mat.Plan.Revision,mat.Plan.Rows,Complete:true,MarkupPercent:12,ChargeContractVersion:2,EvidenceContractVersion:1,ExpectedAcceptedBomVersion:2),author);
Check(J(mat.Plan.Rows)==J(JsonSerializer.Deserialize<SimMaterialPlan>(materialBefore,opt)!.Rows),"post-amendment save preserves material row content");
var restarted=new SimRfqIntakeStore(root);
Check((await restarted.ReadCustomerIdentity(id,author)).Accepted.Version==2,"reopen persists amended version");
Check((await restarted.ReadMaterials(id)).Plan.BomVersion==1,"commercial evidence remains on original version");
var records=JsonNode.Parse(File.ReadAllText(intakePath))!["records"]!.AsArray();
var unrelatedAfter=records.Single(r=>(string?)r!["intakeId"]=="ISOLATED-UNRELATED")!;
Check(J(unrelatedAfter.Deserialize<SimRfqIntakeRecord>(opt)!)==J(unrelated.Deserialize<SimRfqIntakeRecord>(opt)!),"unrelated scenario unchanged");
Check(originalFiles.All(p=>p.Value==Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(p.Key)))),"original source binaries and metadata unchanged");
File.WriteAllText(Path.Combine(root,"accepted-view.json"),J(view));File.WriteAllText(Path.Combine(root,"material-view.json"),J(mat));
var final=await api.ReadFinalReview(id);
Check(final.Summary.LaborComplete,"completed Labor remains eligible for final review");
var approval=await api.ApproveFinalReview(id,new(final.SourceToken,final.Approvals.Length,new("10 Days",false,false,true,"LOW","","STANDARD",false,"")),author);
Check(approval.ApprovalCurrent,"amended BOM and original commercial versions can complete final review");
view=await api.ReadCustomerIdentity(id,author);
Check(!view.CanAmend,"approved quote cannot be silently amended");
await Reject(()=>api.SaveCustomerIdentity(id,req with{ExpectedToken=view.Token},null,author),"CUSTOMER_IDENTITY_CLOSED");
var quote=new SimOrderQuoteBaseline(new(id,"TEST-QUOTE",approval.Approvals.Last().Id,approval.Approvals.Last().Version),record["customer"]!.Deserialize<SimRfqIntakeCustomer>(opt)!,approval.Approvals.Last(),"ACTIVE","SUBMITTED",DateTimeOffset.UtcNow,null,"TEST",[]);
var baselineTask=(Task<SimOrderTechnicalBaseline?>)typeof(SimRfqIntakeStore).GetMethod("OrderTechnicalBaseline",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic)!.Invoke(api,[quote])!;
Check(await baselineTask is not null,"approved amendment preserves technical baseline for future order intake");
// Corrupt only the isolated fixture to prove commercial compatibility cannot hide other edits.
var corrupt=JsonNode.Parse(File.ReadAllText(intakePath))!;corrupt["records"]![0]!["technicalReview"]!["workflow"]!["outputs"]!["materials"]!["candidate"]!["rows"]![0]!["values"]!["quantity"]="999";
File.WriteAllText(intakePath,corrupt.ToJsonString());
await Reject(()=>new SimRfqIntakeStore(root).ReadMaterials(id),"MATERIALS_SOURCE_CHANGED");
Console.WriteLine($"PASS {checks} checks. Isolated fixture: {root}");
